// 新四命令与独立段的窄格式门；本测试不把解码通过称为实际生前授权或身后清算。
#include "../../../src/resident/domains/commerce/liquidation/private_shop_liquidation_boundary.hpp"
#include <iostream>
using namespace hanmo::resident;
namespace {int failed=0,checks=0;void check(bool ok,const char* label){++checks;if(!ok){++failed;std::cerr<<label<<'\n';}}}
int main(){using V=BoundaryValue;using boundary::obj;
    for(const PrivateShopLiquidationCommand& c:std::vector<PrivateShopLiquidationCommand>{PrivateShopAppointExecutor{"shop","policy"},PrivateShopAcceptExecutorship{"shop","policy"},PrivateShopRevokeExecutor{"mandate","revoke"},PrivateShopEstateClose{"shop","mandate","notice"}}){auto raw=encode_private_shop_liquidation_command(c);auto decoded=decode_private_shop_liquidation_command(private_shop_liquidation_command_kind(c),raw);check(decoded.ok,"exact command decoder");if(decoded.ok)check(compare_boundary(raw,encode_private_shop_liquidation_command(decoded.value)).exact(),"exact parameters roundtrip");}
    check(!decode_private_shop_liquidation_command("private_shop_estate_close",obj({{"shop_id",V{StableId{"shop"}}},{"mandate_fact_id",V{StableId{"mandate"}}}})).ok,"missing actual received notice is not defaulted");
    check(!decode_private_shop_liquidation_command("private_shop_appoint_executor",obj({{"shop_id",V{StableId{"shop"}}},{"policy_id",V{StableId{"policy"}}},{"executor_actor_id",V{StableId{"forged"}}}})).ok,"caller cannot override policy party");
    check(!decode_private_shop_liquidation_command("private_shop_revoke_executor",obj({{"mandate_fact_id",V{StableId{"mandate"}}},{"decision",V{StableId{"operate"}}}})).ok,"unknown executor powers rejected");
    check(!decode_private_shop_liquidation_command("private_shop_close",obj({{"shop_id",V{StableId{"shop"}}}})).ok,"old proprietor command is not new executor command");
    check(!decode_private_shop_liquidation_command("private_shop_appoint_executor",obj({{"shop_id",V{StableId{"a"}}},{"shop_id",V{StableId{"b"}}},{"policy_id",V{StableId{"policy"}}}})).ok,"duplicate command field rejected");
    PrivateShopLiquidationState state;auto raw=encode_private_shop_liquidations(state);check(decode_private_shop_liquidations(raw).ok,"empty independent state roundtrip");auto missing=raw;auto* fields=missing.as<V::Dict>();fields->erase(std::remove_if(fields->begin(),fields->end(),[](const auto& p){return p.first=="closings";}),fields->end());check(!decode_private_shop_liquidations(missing).ok,"state cannot omit original receipt table");auto bad=raw;bad.as<V::Dict>()->push_back({"wallet_balance",V{Integer{5}}});check(!decode_private_shop_liquidations(bad).ok,"no second asset ledger accepted");bad=raw;for(auto& p:*bad.as<V::Dict>())if(p.first=="version")p.second=V{Integer{2}};check(!decode_private_shop_liquidations(bad).ok,"unknown state version rejected");
    auto legacy=decode_private_shop_liquidation_profile(obj({}),{});check(legacy.ok&&!legacy.value,"legacy profile stays disabled");auto selected=obj({{"dynamic_world",obj({{"private_shop_liquidations",obj({{"version",V{Integer{1}}},{"policies",obj({})}})}})}});check(!decode_private_shop_liquidation_profile(selected,{}).ok,"new block requires explicit dependencies");
    std::vector<std::pair<StableId,StableId>> modules;for(const auto* name:{"private_shop_liquidations","task_shop_order_estate_cancellations","private_shops","task_shop_orders","family_life","task_message_notices","task_message_handoffs"})modules.emplace_back(name,"1");check(validate_private_shop_liquidation_pair(true,modules).ok,"strict complete liquidation pair");for(std::size_t i=0;i<modules.size();++i){auto missing=modules;missing.erase(missing.begin()+i);check(!validate_private_shop_liquidation_pair(true,missing).ok,"every actual old and new module required");}check(!validate_private_shop_liquidation_pair(false,modules).ok,"disabled profile rejects new tail");auto duplicate=modules;duplicate.push_back(modules.front());check(!validate_private_shop_liquidation_pair(true,duplicate).ok,"duplicate module rejected");auto unknown=modules;unknown.front().second="2";check(!validate_private_shop_liquidation_pair(true,unknown).ok,"unknown liquidation version rejected");check(validate_private_shop_liquidation_pair(false,{{"task_message_handoffs","future"}}).ok,"legacy unrelated selection is not owned by this pair");
    std::cout<<checks<<'/'<<failed<<" estate boundary source checks\n";return failed?1:0;
}
